// TEMPORARY verification helper (deleted after use).
// Transpiles the files under test with the TypeScript API into _verify/out
// as ESM, rewriting "@/..." and relative imports to .mjs paths.
import ts from "typescript";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, posix } from "node:path";

const root = process.cwd();
const outRoot = join(root, "_verify", "out");
const files = [
  "components/CandidateResearch.tsx",
  "components/CitedText.tsx",
  "lib/format.ts",
  "lib/candidates.ts",
  "lib/articles.ts",
  "lib/politicians.ts",
  "lib/candidate-profiles.ts",
  "lib/supabase/server.ts",
  "lib/types.ts",
  "_verify/render-check.tsx",
];

for (const rel of files) {
  const source = readFileSync(join(root, rel), "utf8");
  const { outputText } = ts.transpileModule(source, {
    fileName: rel,
    compilerOptions: {
      module: ts.ModuleKind.ESNext,
      target: ts.ScriptTarget.ES2022,
      jsx: ts.JsxEmit.ReactJSX,
    },
  });

  const fromDir = posix.dirname(rel);
  const rewritten = outputText.replace(
    /(\bfrom\s+|\bimport\s*\(\s*|\bimport\s+)(["'])([^"']+)\2/g,
    (match, prefix, quote, spec) => {
      let target;
      if (spec.startsWith("@/")) target = spec.slice(2);
      else if (spec.startsWith(".")) target = posix.join(fromDir, spec);
      else return match;
      let relPath = posix.relative(fromDir, target);
      if (!relPath.startsWith(".")) relPath = `./${relPath}`;
      return `${prefix}${quote}${relPath}.mjs${quote}`;
    }
  );

  const dest = join(outRoot, rel.replace(/\.(tsx|ts)$/, ".mjs"));
  mkdirSync(dirname(dest), { recursive: true });
  writeFileSync(dest, rewritten, "utf8");
}
console.log(`Transpiled ${files.length} files`);

// TEMPORARY verification script (deleted after use).
// Stubs Supabase with the seed data, runs the real getCandidates() merge, and
// server-renders the research UI for every candidate.
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { renderToString } from "react-dom/server";
import CandidateResearch from "../components/CandidateResearch";
import { CANDIDATE_PROFILES } from "../lib/candidate-profiles";
